import { ScrollArea as BaseScrollArea } from '@base-ui/react/scroll-area';
import type { ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { scrollAreaVariants } from './scroll-area.variants';

export interface ScrollAreaProps extends Omit<BaseScrollArea.Root.Props, 'className' | 'children'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  children?: ReactNode;
  /** Which scrollbars to draw. Default `vertical`. */
  orientation?: 'vertical' | 'horizontal' | 'both';
  /** Draws a bordered card surface around the area. */
  bordered?: boolean;
  /**
   * Accessible name of the scrollable region. When set (or `aria-labelledby`), the viewport becomes a
   * labelled `role="region"`; it joins the Tab order whenever its content overflows.
   */
  'aria-label'?: string;
  'aria-labelledby'?: string;
  /** Class for the viewport (the scroll container). */
  viewportClassName?: string;
  /** Class for the content wrapper inside the viewport (padding goes here). */
  contentClassName?: string;
  viewportRef?: Ref<HTMLDivElement>;
}

/**
 * Native scroll container with thin, token-styled scrollbars that fade in on hover and while
 * scrolling. Overflowing viewports are focusable (Tab), so arrow keys / Page keys scroll natively.
 */
export function ScrollArea({
  orientation = 'vertical',
  bordered,
  className,
  viewportClassName,
  contentClassName,
  viewportRef,
  children,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledBy,
  ...props
}: ScrollAreaProps) {
  const s = scrollAreaVariants({ bordered });
  const labelled = ariaLabel != null || ariaLabelledBy != null;
  return (
    <BaseScrollArea.Root className={cn(s.root(), className)} {...props}>
      <BaseScrollArea.Viewport
        ref={viewportRef}
        className={cn(s.viewport(), viewportClassName)}
        {...(labelled ? { role: 'region', 'aria-label': ariaLabel, 'aria-labelledby': ariaLabelledBy } : {})}
      >
        <BaseScrollArea.Content className={cn(s.content(), orientation !== 'vertical' && 'min-w-fit', contentClassName)}>
          {children}
        </BaseScrollArea.Content>
      </BaseScrollArea.Viewport>
      {orientation !== 'horizontal' && (
        <BaseScrollArea.Scrollbar orientation="vertical" className={s.scrollbar()}>
          <BaseScrollArea.Thumb className={s.thumb()} />
        </BaseScrollArea.Scrollbar>
      )}
      {orientation !== 'vertical' && (
        <BaseScrollArea.Scrollbar orientation="horizontal" className={s.scrollbar()}>
          <BaseScrollArea.Thumb className={s.thumb()} />
        </BaseScrollArea.Scrollbar>
      )}
      {orientation === 'both' && <BaseScrollArea.Corner className={s.corner()} />}
    </BaseScrollArea.Root>
  );
}

export { ScrollArea, type ScrollAreaProps } from './ScrollArea';
export { scrollAreaVariants, type ScrollAreaVariantProps } from './scroll-area.variants';
export { doc as scrollAreaDoc } from './ScrollArea.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const scrollAreaVariants = tv({
  slots: {
    root: 'relative min-h-0 overflow-hidden',
    viewport:
      'size-full overscroll-contain rounded-[inherit] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-focus-ring',
    content: '',
    scrollbar:
      'pointer-events-none flex touch-none p-0.5 opacity-0 transition-opacity duration-150 select-none motion-reduce:transition-none data-hovering:pointer-events-auto data-hovering:opacity-100 data-scrolling:pointer-events-auto data-scrolling:opacity-100 data-scrolling:duration-0 data-[orientation=horizontal]:h-2.5 data-[orientation=horizontal]:flex-col data-[orientation=vertical]:w-2.5',
    thumb: 'flex-1 rounded-full bg-border hover:bg-muted-foreground/50 active:bg-muted-foreground/60',
    corner: 'bg-transparent',
  },
  variants: {
    bordered: {
      true: { root: 'rounded-lg border border-border bg-card' },
    },
  },
  defaultVariants: { bordered: false },
});

export type ScrollAreaVariantProps = VariantProps<typeof scrollAreaVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'ScrollArea',
  group: 'Layout',
  status: 'stable',
  description:
    'Native scroll container with thin token-styled scrollbars that fade in on hover and while scrolling. Vertical, horizontal or both; optional bordered surface. With an aria-label the viewport is a named region, and it joins the Tab order whenever it overflows.',
  primitive: '@base-ui/react/scroll-area',
  pattern: 'region',
  keyboard: [
    ['Tab', 'Focuses the scrollable viewport (only when its content overflows)'],
    ['ArrowUp / ArrowDown / PageUp / PageDown / Home / End', 'Scrolls the focused viewport natively'],
  ],
  tokens: ['border', 'muted-foreground', 'card', 'focus-ring'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
